Lemma bput_closed : forall MX CX MA' MR, bput_stmt H MX CX MA' MR.
Proof.
  intros MX CX MA' MR.
  exact (bput_spec H HH MX CX MA' MR (ah_memset H HH) cl_spec (obinit_spec (ah_memset H HH)) (on_finish_impl_spec (ah_memset H HH))
           psl_seg1 (psl_seg2 (ah_memcpy H HH) Y_ASSIGNA) Y_ISL pf_seg1 (pf_seg2 (ah_memcpy H HH) Y_ASSIGNA) Y_IPF Y_FH
           (pb_seg1 (ah_memset H HH)) (pb_seg2 (ah_memset H HH)) Y_OBI Y_PCH Y_OCB).
Qed.
